using System.Runtime.CompilerServices;

namespace Ladder.Json;

/// <summary>One bit per nesting level (set = object, clear = array), stored inline so the tokenizer never allocates.</summary>
internal struct DepthBits
{
    public const int Capacity = Words.Length * 64;

    private Words _words;

    public bool this[int depth]
    {
        readonly get => (_words[depth >> 6] & (1UL << (depth & 63))) != 0;
        set
        {
            if (value)
            {
                _words[depth >> 6] |= 1UL << (depth & 63);
            }
            else
            {
                _words[depth >> 6] &= ~(1UL << (depth & 63));
            }
        }
    }

    [InlineArray(Length)]
    private struct Words
    {
        public const int Length = 8;

        private ulong _element;
    }
}

using System.Buffers;

namespace Ladder.Json;

public static class JsonDocumentParser
{
    /// <summary>Parses a whole document into a <see cref="JsonValue"/> tree using an explicit stack, so input depth cannot overflow the call stack.</summary>
    public static bool TryParse(ReadOnlySpan<byte> utf8Json, out JsonValue? value, out JsonParseError error, int maxDepth = JsonTokenizer.MaxSupportedDepth)
    {
        var tokenizer = new JsonTokenizer(utf8Json, maxDepth);
        var containers = new Stack<JsonValue>();
        string? pendingName = null;
        value = null;
        char[]? scratch = null;

        try
        {
            while (tokenizer.Read())
            {
                JsonValue? completed;
                switch (tokenizer.Kind)
                {
                    case JsonTokenKind.StartObject:
                        containers.Push(Attach(new JsonObject(), containers, ref pendingName));
                        continue;
                    case JsonTokenKind.StartArray:
                        containers.Push(Attach(new JsonArray(), containers, ref pendingName));
                        continue;
                    case JsonTokenKind.EndObject:
                    case JsonTokenKind.EndArray:
                        completed = containers.Pop();
                        if (containers.Count == 0)
                        {
                            value = completed;
                        }

                        continue;
                    case JsonTokenKind.PropertyName:
                        if (!TryDecode(ref tokenizer, ref scratch, out pendingName, out error))
                        {
                            return false;
                        }

                        continue;
                    case JsonTokenKind.String:
                        if (!TryDecode(ref tokenizer, ref scratch, out string? s, out error))
                        {
                            return false;
                        }

                        completed = new JsonStringValue(s!);
                        break;
                    case JsonTokenKind.Number:
                        completed = new JsonNumber(System.Text.Encoding.ASCII.GetString(tokenizer.ValueSpan));
                        break;
                    case JsonTokenKind.True:
                        completed = JsonLiteral.True;
                        break;
                    case JsonTokenKind.False:
                        completed = JsonLiteral.False;
                        break;
                    default:
                        completed = JsonLiteral.Null;
                        break;
                }

                Attach(completed, containers, ref pendingName);
                if (containers.Count == 0)
                {
                    value = completed;
                }
            }

            error = tokenizer.Error;
            if (error.IsError)
            {
                value = null;
                return false;
            }

            return true;
        }
        finally
        {
            if (scratch is not null)
            {
                ArrayPool<char>.Shared.Return(scratch);
            }
        }
    }

    private static JsonValue Attach(JsonValue child, Stack<JsonValue> containers, ref string? pendingName)
    {
        if (containers.TryPeek(out JsonValue? parent))
        {
            if (parent is JsonObject obj)
            {
                obj.Members.Add(new(pendingName!, child));
                pendingName = null;
            }
            else
            {
                ((JsonArray)parent).Items.Add(child);
            }
        }

        return child;
    }

    private static bool TryDecode(ref JsonTokenizer tokenizer, ref char[]? scratch, out string? text, out JsonParseError error)
    {
        ReadOnlySpan<byte> raw = tokenizer.ValueSpan;
        if (scratch is null || scratch.Length < raw.Length)
        {
            if (scratch is not null)
            {
                ArrayPool<char>.Shared.Return(scratch);
            }

            scratch = ArrayPool<char>.Shared.Rent(Math.Max(raw.Length, 64));
        }

        OperationStatus status = tokenizer.TryGetString(scratch, out int written, out JsonErrorReason reason);
        if (status != OperationStatus.Done)
        {
            text = null;
            error = new JsonParseError(tokenizer.TokenOffset, reason == JsonErrorReason.None ? JsonErrorReason.InvalidUtf8 : reason);
            return false;
        }

        text = new string(scratch, 0, written);
        error = default;
        return true;
    }
}

namespace Ladder.Json;

public enum JsonErrorReason : byte
{
    None,
    UnexpectedEndOfInput,
    UnexpectedByte,
    ExpectedPropertyName,
    ExpectedColon,
    InvalidLiteral,
    InvalidNumber,
    InvalidEscape,
    ControlCharacterInString,
    InvalidUtf8,
    InvalidSurrogate,
    MaxDepthExceeded,
}

/// <summary>Where and why parsing stopped. <see cref="Offset"/> is a byte offset into the input.</summary>
public readonly record struct JsonParseError(int Offset, JsonErrorReason Reason)
{
    public bool IsError => Reason != JsonErrorReason.None;

    public override string ToString() => IsError ? $"{Reason} at byte {Offset}" : "None";
}

using System.Buffers;
using System.Text.Unicode;

namespace Ladder.Json;

public static class JsonString
{
    /// <summary>
    /// Decodes a raw JSON string body (already validated by <see cref="JsonTokenizer"/>) into UTF-16.
    /// Unpaired surrogate escapes such as <c>"\uD800"</c> are rejected with <see cref="JsonErrorReason.InvalidSurrogate"/>.
    /// </summary>
    public static OperationStatus Unescape(ReadOnlySpan<byte> raw, Span<char> destination, out int charsWritten, out JsonErrorReason error)
    {
        charsWritten = 0;
        error = JsonErrorReason.None;
        while (true)
        {
            int backslash = raw.IndexOf((byte)'\\');
            ReadOnlySpan<byte> literal = backslash < 0 ? raw : raw[..backslash];
            OperationStatus status = Utf8.ToUtf16(literal, destination[charsWritten..], out _, out int written, replaceInvalidSequences: false);
            charsWritten += written;
            if (status != OperationStatus.Done)
            {
                error = status == OperationStatus.InvalidData ? JsonErrorReason.InvalidUtf8 : JsonErrorReason.None;
                return status;
            }

            if (backslash < 0)
            {
                return OperationStatus.Done;
            }

            raw = raw[backslash..];
            if (charsWritten >= destination.Length)
            {
                return OperationStatus.DestinationTooSmall;
            }

            char c;
            switch (raw[1])
            {
                case (byte)'b': c = '\b'; break;
                case (byte)'f': c = '\f'; break;
                case (byte)'n': c = '\n'; break;
                case (byte)'r': c = '\r'; break;
                case (byte)'t': c = '\t'; break;
                case (byte)'u':
                    c = (char)ParseHex4(raw.Slice(2, 4));
                    if (char.IsHighSurrogate(c))
                    {
                        if (raw.Length < 12 || raw[6] != (byte)'\\' || raw[7] != (byte)'u'
                            || !char.IsLowSurrogate((char)ParseHex4(raw.Slice(8, 4))))
                        {
                            error = JsonErrorReason.InvalidSurrogate;
                            return OperationStatus.InvalidData;
                        }

                        if (charsWritten + 2 > destination.Length)
                        {
                            return OperationStatus.DestinationTooSmall;
                        }

                        destination[charsWritten++] = c;
                        destination[charsWritten++] = (char)ParseHex4(raw.Slice(8, 4));
                        raw = raw[12..];
                        continue;
                    }

                    if (char.IsLowSurrogate(c))
                    {
                        error = JsonErrorReason.InvalidSurrogate;
                        return OperationStatus.InvalidData;
                    }

                    destination[charsWritten++] = c;
                    raw = raw[6..];
                    continue;
                default:
                    // '"', '\\' and '/' stand for themselves.
                    c = (char)raw[1];
                    break;
            }

            destination[charsWritten++] = c;
            raw = raw[2..];
        }
    }

    private static int ParseHex4(ReadOnlySpan<byte> hex)
    {
        int value = 0;
        foreach (byte b in hex)
        {
            value = (value << 4) | HexValue(b);
        }

        return value;
    }

    private static int HexValue(byte b) => b switch
    {
        <= (byte)'9' => b - '0',
        <= (byte)'F' => b - 'A' + 10,
        _ => b - 'a' + 10,
    };
}

