namespace Ladder.Json.Tests;

/// <summary>
/// Properties checked against System.Text.Json as the reference: its writer produces the inputs,
/// and its reader is the oracle for which mutated inputs are valid.
/// </summary>
public class PropertyTests
{
    private static readonly Gen<string> s_text =
        Gen.Frequency(
                (6, Gen.Int[0, 0x7F]),
                (2, Gen.Int[0x80, 0xD7FF]),
                (1, Gen.Int[0xE000, 0xFFFF]),
                (1, Gen.Int[0x10000, 0x10FFFF]))
            .Array[0, 12]
            .Select(codePoints => string.Concat(codePoints.Select(char.ConvertFromUtf32)));

    private static readonly Gen<Model> s_leaf = Gen.OneOf<Model>(
        Gen.Const<Model>(new Model.Null()),
        Gen.Bool.Select(b => (Model)new Model.Bool(b)),
        Gen.Double.Where(double.IsFinite).Select(d => (Model)new Model.Num(d)),
        Gen.Long.Select(l => (Model)new Model.Num(l)),
        s_text.Select(s => (Model)new Model.Str(s)));

    private static readonly Gen<Model> s_model = ModelOfDepth(4);

    private static readonly Gen<(Model Model, byte[] Json)> s_document =
        Gen.Select(s_model, Gen.Bool, Gen.Bool, (model, relaxed, indented) => (model, Write(model, relaxed, indented)));

    [Fact]
    public void Parses_what_System_Text_Json_writes()
    {
        s_document.Sample(
            doc =>
            {
                Assert.True(JsonDocumentParser.TryParse(doc.Json, out JsonValue? tree, out JsonParseError error), error.ToString());
                Assert.True(Same(doc.Model, tree!), Encoding.UTF8.GetString(doc.Json));
            },
            iter: 20_000);
    }

    [Fact]
    public void Mutated_documents_never_throw_and_agree_with_Utf8JsonReader_on_validity()
    {
        Gen<(int Op, double At, byte Value)> mutation = Gen.Select(Gen.Int[0, 2], Gen.Double[0, 1], Gen.Byte);
        Gen<byte[]> mutated = Gen.Select(s_document, mutation.Array[1, 4], (doc, ops) => Mutate(doc.Json, ops));

        mutated.Sample(
            json =>
            {
                bool tokenizerAccepts = TokenizerAccepts(json);
                _ = JsonDocumentParser.TryParse(json, out _, out _);

                // Utf8JsonReader does not validate UTF-8 inside strings, so it is only an oracle for valid UTF-8 input.
                if (Utf8.IsValid(json))
                {
                    Assert.Equal(ReaderAccepts(json), tokenizerAccepts);
                }
            },
            iter: 50_000,
            print: json => Convert.ToHexString(json) + " " + Encoding.UTF8.GetString(json));
    }

    private static Gen<Model> ModelOfDepth(int depth)
    {
        if (depth == 0)
        {
            return s_leaf;
        }

        Gen<Model> child = ModelOfDepth(depth - 1);
        return Gen.Frequency(
            (3, s_leaf),
            (1, child.Array[0, 5].Select(items => (Model)new Model.Arr(items))),
            (1, Gen.Select(s_text, child).Array[0, 5].Select(members => (Model)new Model.Obj(members))));
    }

    private static byte[] Write(Model model, bool relaxed, bool indented)
    {
        var buffer = new ArrayBufferWriter<byte>();
        var options = new JsonWriterOptions
        {
            Encoder = relaxed ? JavaScriptEncoder.UnsafeRelaxedJsonEscaping : JavaScriptEncoder.Default,
            Indented = indented,
            SkipValidation = true,
        };
        using (var writer = new Utf8JsonWriter(buffer, options))
        {
            WriteValue(writer, model);
        }

        return buffer.WrittenSpan.ToArray();
    }

    private static void WriteValue(Utf8JsonWriter writer, Model model)
    {
        switch (model)
        {
            case Model.Null:
                writer.WriteNullValue();
                break;
            case Model.Bool b:
                writer.WriteBooleanValue(b.Value);
                break;
            case Model.Num n:
                writer.WriteNumberValue(n.Value);
                break;
            case Model.Str s:
                writer.WriteStringValue(s.Value);
                break;
            case Model.Arr a:
                writer.WriteStartArray();
                foreach (Model item in a.Items)
                {
                    WriteValue(writer, item);
                }

                writer.WriteEndArray();
                break;
            case Model.Obj o:
                writer.WriteStartObject();
                foreach ((string name, Model value) in o.Members)
                {
                    writer.WritePropertyName(name);
                    WriteValue(writer, value);
                }

                writer.WriteEndObject();
                break;
        }
    }

    private static bool Same(Model model, JsonValue value) => (model, value) switch
    {
        (Model.Null, JsonLiteral l) => l.Kind == JsonTokenKind.Null,
        (Model.Bool b, JsonLiteral l) => l.Kind == (b.Value ? JsonTokenKind.True : JsonTokenKind.False),
        (Model.Num n, JsonNumber j) => double.Parse(j.Raw, System.Globalization.CultureInfo.InvariantCulture).Equals(n.Value),
        (Model.Str s, JsonStringValue j) => string.Equals(s.Value, j.Value, StringComparison.Ordinal),
        (Model.Arr a, JsonArray j) => a.Items.Length == j.Items.Count && a.Items.Zip(j.Items).All(p => Same(p.First, p.Second)),
        (Model.Obj o, JsonObject j) => o.Members.Length == j.Members.Count
            && o.Members.Zip(j.Members).All(p => string.Equals(p.First.Name, p.Second.Key, StringComparison.Ordinal) && Same(p.First.Value, p.Second.Value)),
        _ => false,
    };

    private static byte[] Mutate(byte[] json, (int Op, double At, byte Value)[] ops)
    {
        var bytes = new List<byte>(json);
        foreach ((int op, double at, byte value) in ops)
        {
            int i = (int)(at * bytes.Count);
            switch (op)
            {
                case 0 when bytes.Count > 0:
                    bytes[Math.Min(i, bytes.Count - 1)] = value;
                    break;
                case 1:
                    bytes.Insert(i, value);
                    break;
                case 2 when bytes.Count > 0:
                    bytes.RemoveAt(Math.Min(i, bytes.Count - 1));
                    break;
            }
        }

        return [.. bytes];
    }

    private static bool TokenizerAccepts(byte[] json)
    {
        var t = new JsonTokenizer(json);
        while (t.Read())
        {
        }

        return !t.Error.IsError;
    }

    private static bool ReaderAccepts(byte[] json)
    {
        try
        {
            var reader = new Utf8JsonReader(json, new JsonReaderOptions { MaxDepth = JsonTokenizer.MaxSupportedDepth });
            int tokens = 0;
            while (reader.Read())
            {
                tokens++;
            }

            // An empty or whitespace-only input reads zero tokens without throwing; RFC 8259 requires a value.
            return tokens > 0;
        }
        catch (JsonException)
        {
            return false;
        }
    }

    internal abstract record Model
    {
        internal sealed record Null : Model;

        internal sealed record Bool(bool Value) : Model;

        internal sealed record Num(double Value) : Model;

        internal sealed record Str(string Value) : Model;

        internal sealed record Arr(Model[] Items) : Model;

        internal sealed record Obj((string Name, Model Value)[] Members) : Model;
    }
}

using System.Buffers;
using System.Text;

namespace Ladder.Json.Tests;

public class StringTests
{
    [Theory]
    [InlineData("plain", "plain")]
    [InlineData("\\\"\\\\\\/\\b\\f\\n\\r\\t", "\"\\/\b\f\n\r\t")]
    [InlineData("\\u0041\\u00e9\\u00E9", "Aéé")]
    [InlineData("\\uD83D\\uDE00", "😀")]
    [InlineData("é\\n😀x", "é\n😀x")]
    [InlineData("\\uFFFF", "\uFFFF")]
    public void Unescapes(string raw, string expected)
    {
        Assert.Equal(expected, Decode(raw, out _));
    }

    [Theory]
    [InlineData("\\uD800")]
    [InlineData("\\uD800x")]
    [InlineData("\\uDC00")]
    [InlineData("\\uD800\\u0041")]
    [InlineData("\\uD800\\\\u0041")]
    [InlineData("\\uD800\\uD800")]
    [InlineData("\\uD800\\n")]
    public void Rejects_unpaired_surrogates(string raw)
    {
        Assert.Null(Decode(raw, out JsonErrorReason reason));
        Assert.Equal(JsonErrorReason.InvalidSurrogate, reason);
    }

    [Fact]
    public void Rejects_invalid_utf8()
    {
        OperationStatus status = JsonString.Unescape([(byte)'a', 0xFF], new char[4], out _, out JsonErrorReason reason);
        Assert.Equal(OperationStatus.InvalidData, status);
        Assert.Equal(JsonErrorReason.InvalidUtf8, reason);
    }

    [Theory]
    [InlineData("abc", 2)]
    [InlineData("a\\n", 1)]
    [InlineData("\\uD83D\\uDE00", 1)]
    [InlineData("\\u0041", 0)]
    public void Reports_destination_too_small(string raw, int size)
    {
        Assert.Equal(OperationStatus.DestinationTooSmall, JsonString.Unescape(Encoding.UTF8.GetBytes(raw), new char[size], out _, out JsonErrorReason reason));
        Assert.Equal(JsonErrorReason.None, reason);
    }

    [Fact]
    public void Surrogate_pair_fits_a_buffer_of_exactly_two()
    {
        Assert.Equal(OperationStatus.Done, JsonString.Unescape("\\uD83D\\uDE00"u8, new char[2], out int written, out _));
        Assert.Equal(2, written);
    }

    [Fact]
    public void Raw_length_is_always_a_large_enough_buffer()
    {
        // Each escape is at least as long in bytes as its UTF-16 output, and each UTF-8 byte yields at most one char.
        byte[] raw = Encoding.UTF8.GetBytes("\\uD83D\\uDE00é😀\\n");
        var buffer = new char[raw.Length];
        Assert.Equal(OperationStatus.Done, JsonString.Unescape(raw, buffer, out int written, out _));
        Assert.Equal("😀é😀\n", new string(buffer, 0, written));
    }

    private static string? Decode(string raw, out JsonErrorReason reason)
    {
        byte[] bytes = Encoding.UTF8.GetBytes(raw);
        var buffer = new char[bytes.Length];
        OperationStatus status = JsonString.Unescape(bytes, buffer, out int written, out reason);
        return status == OperationStatus.Done ? new string(buffer, 0, written) : null;
    }
}

using System.Buffers;
using System.Text;

namespace Ladder.Json.Tests;

public class TokenizerTests
{
    [Theory]
    [InlineData("0")]
    [InlineData("-0")]
    [InlineData("-0.0e-0")]
    [InlineData("1E+2")]
    [InlineData("123.456e789")]
    [InlineData("\"\"")]
    [InlineData("\"\\\"\\\\\\/\\b\\f\\n\\r\\t\\u00e9\"")]
    [InlineData(" \t\r\n[ ] ")]
    [InlineData("{\"a\":[true,false,null],\"a\":{}}")]
    [InlineData("\"é😀\"")]
    public void Accepts_valid_documents(string json)
    {
        Assert.Equal(default, Tokenize(json, out _));
    }

    [Theory]
    [InlineData("", 0, JsonErrorReason.UnexpectedEndOfInput)]
    [InlineData("   ", 3, JsonErrorReason.UnexpectedEndOfInput)]
    [InlineData("01", 1, JsonErrorReason.UnexpectedByte)]
    [InlineData("-", 1, JsonErrorReason.InvalidNumber)]
    [InlineData("-a", 1, JsonErrorReason.InvalidNumber)]
    [InlineData("1.", 2, JsonErrorReason.InvalidNumber)]
    [InlineData("1.e3", 2, JsonErrorReason.InvalidNumber)]
    [InlineData("1e", 2, JsonErrorReason.InvalidNumber)]
    [InlineData("1e+", 3, JsonErrorReason.InvalidNumber)]
    [InlineData(".5", 0, JsonErrorReason.UnexpectedByte)]
    [InlineData("+1", 0, JsonErrorReason.UnexpectedByte)]
    [InlineData("tru", 0, JsonErrorReason.InvalidLiteral)]
    [InlineData("nul", 0, JsonErrorReason.InvalidLiteral)]
    [InlineData("fals", 0, JsonErrorReason.InvalidLiteral)]
    [InlineData("truex", 4, JsonErrorReason.UnexpectedByte)]
    [InlineData("[1,]", 3, JsonErrorReason.UnexpectedByte)]
    [InlineData("[1 2]", 3, JsonErrorReason.UnexpectedByte)]
    [InlineData("[1}", 2, JsonErrorReason.UnexpectedByte)]
    [InlineData("{]", 1, JsonErrorReason.ExpectedPropertyName)]
    [InlineData("{\"a\":1]", 6, JsonErrorReason.UnexpectedByte)]
    [InlineData("{\"a\":1,}", 7, JsonErrorReason.ExpectedPropertyName)]
    [InlineData("{\"a\" 1}", 5, JsonErrorReason.ExpectedColon)]
    [InlineData("{\"a\"", 4, JsonErrorReason.UnexpectedEndOfInput)]
    [InlineData("{1:2}", 1, JsonErrorReason.ExpectedPropertyName)]
    [InlineData("[", 1, JsonErrorReason.UnexpectedEndOfInput)]
    [InlineData("[1,", 3, JsonErrorReason.UnexpectedEndOfInput)]
    [InlineData("\"abc", 4, JsonErrorReason.UnexpectedEndOfInput)]
    [InlineData("\"a\tb\"", 2, JsonErrorReason.ControlCharacterInString)]
    [InlineData("\"\\x\"", 1, JsonErrorReason.InvalidEscape)]
    [InlineData("\"\\u12G4\"", 1, JsonErrorReason.InvalidEscape)]
    [InlineData("\"\\u12", 5, JsonErrorReason.UnexpectedEndOfInput)]
    [InlineData("\"\\", 2, JsonErrorReason.UnexpectedEndOfInput)]
    [InlineData("1 2", 2, JsonErrorReason.UnexpectedByte)]
    [InlineData("[\"\\q\"]", 2, JsonErrorReason.InvalidEscape)]
    [InlineData("{\"\\q\":1}", 2, JsonErrorReason.InvalidEscape)]
    [InlineData("{\"a\":\"\\q\"}", 6, JsonErrorReason.InvalidEscape)]
    [InlineData("[]]", 2, JsonErrorReason.UnexpectedByte)]
    [InlineData("\u00a0[]", 0, JsonErrorReason.UnexpectedByte)]
    public void Rejects_with_reason_and_offset(string json, int offset, JsonErrorReason reason)
    {
        Assert.Equal(new JsonParseError(offset, reason), Tokenize(json, out _));
    }

    [Fact]
    public void Rejects_invalid_utf8_inside_strings()
    {
        byte[] json = [(byte)'"', (byte)'a', 0xC3, (byte)'"'];
        Assert.Equal(new JsonParseError(1, JsonErrorReason.InvalidUtf8), Tokenize(json, out _));
    }

    [Fact]
    public void Rejects_utf8_byte_order_mark()
    {
        byte[] json = [0xEF, 0xBB, 0xBF, (byte)'[', (byte)']'];
        Assert.Equal(new JsonParseError(0, JsonErrorReason.UnexpectedByte), Tokenize(json, out _));
    }

    [Fact]
    public void Emits_tokens_in_document_order()
    {
        Tokenize("{\"k\":[1,\"s\",true,false,null],\"e\":{}}", out List<(JsonTokenKind Kind, string Value, int Offset)> tokens);
        Assert.Equal(
            [
                (JsonTokenKind.StartObject, "", 0),
                (JsonTokenKind.PropertyName, "k", 1),
                (JsonTokenKind.StartArray, "", 5),
                (JsonTokenKind.Number, "1", 6),
                (JsonTokenKind.String, "s", 8),
                (JsonTokenKind.True, "", 12),
                (JsonTokenKind.False, "", 17),
                (JsonTokenKind.Null, "", 23),
                (JsonTokenKind.EndArray, "", 27),
                (JsonTokenKind.PropertyName, "e", 29),
                (JsonTokenKind.StartObject, "", 33),
                (JsonTokenKind.EndObject, "", 34),
                (JsonTokenKind.EndObject, "", 35),
            ],
            tokens);
    }

    [Fact]
    public void Read_after_end_or_error_keeps_returning_false()
    {
        var ok = new JsonTokenizer("1"u8);
        Assert.True(ok.Read());
        Assert.False(ok.Read());
        Assert.False(ok.Read());
        Assert.Equal(JsonTokenKind.None, ok.Kind);

        var bad = new JsonTokenizer("[x"u8);
        Assert.True(bad.Read());
        Assert.False(bad.Read());
        Assert.False(bad.Read());
        Assert.Equal(new JsonParseError(1, JsonErrorReason.UnexpectedByte), bad.Error);
    }

    [Fact]
    public void Depth_limit_is_exact()
    {
        Assert.Equal(default, Tokenize("[[{\"a\":[]}]]", out _, maxDepth: 4));
        Assert.Equal(new JsonParseError(7, JsonErrorReason.MaxDepthExceeded), Tokenize("[[{\"a\":[]}]]", out _, maxDepth: 3));
        Assert.Equal(new JsonParseError(5, JsonErrorReason.MaxDepthExceeded), Tokenize("{\"a\":{}}", out _, maxDepth: 1));
    }

    [Fact]
    public void Default_depth_limit_accepts_512_and_rejects_513()
    {
        Assert.Equal(default, Tokenize(new string('[', 512) + new string(']', 512), out _));
        Assert.Equal(new JsonParseError(512, JsonErrorReason.MaxDepthExceeded), Tokenize(new string('[', 513) + new string(']', 513), out _));
    }

    [Fact]
    public void Nesting_past_the_limit_fails_without_stack_overflow()
    {
        Assert.Equal(JsonErrorReason.MaxDepthExceeded, Tokenize(new string('[', 100_000), out _).Reason);
    }

    [Fact]
    public void Depth_bits_track_objects_and_arrays_across_word_boundaries()
    {
        // Alternate object/array nesting past 64 levels so the close for each level is checked against the right bit.
        var sb = new StringBuilder();
        for (int i = 0; i < 200; i++)
        {
            sb.Append(i % 2 == 0 ? "{\"k\":" : "[");
        }

        sb.Append('0');
        for (int i = 199; i >= 0; i--)
        {
            sb.Append(i % 2 == 0 ? '}' : ']');
        }

        Assert.Equal(default, Tokenize(sb.ToString(), out _));
    }

    [Theory]
    [InlineData(0)]
    [InlineData(JsonTokenizer.MaxSupportedDepth + 1)]
    public void Rejects_unsupported_max_depth(int maxDepth)
    {
        Assert.Throws<ArgumentOutOfRangeException>(() => new JsonTokenizer("1"u8, maxDepth));
    }

    [Theory]
    [InlineData("0", 0d)]
    [InlineData("-12.5e1", -125d)]
    [InlineData("1e400", double.PositiveInfinity)]
    public void TryGetDouble_parses_number_tokens(string json, double expected)
    {
        var t = new JsonTokenizer(Encoding.UTF8.GetBytes(json));
        Assert.True(t.Read());
        Assert.True(t.TryGetDouble(out double value));
        Assert.Equal(expected, value);
    }

    [Fact]
    public void Typed_getters_refuse_other_token_kinds()
    {
        var t = new JsonTokenizer("\"1\""u8);
        Assert.True(t.Read());
        Assert.False(t.TryGetDouble(out _));
        Assert.False(t.TryGetInt64(out _));

        var n = new JsonTokenizer("1"u8);
        Assert.True(n.Read());
        Assert.Equal(OperationStatus.InvalidData, n.TryGetString(new char[8], out _, out _));
    }

    [Theory]
    [InlineData("9223372036854775807", true, long.MaxValue)]
    [InlineData("-9223372036854775808", true, long.MinValue)]
    [InlineData("9223372036854775808", false, 0L)]
    [InlineData("1.0", false, 0L)]
    public void TryGetInt64_accepts_only_in_range_integers(string json, bool ok, long expected)
    {
        var t = new JsonTokenizer(Encoding.UTF8.GetBytes(json));
        Assert.True(t.Read());
        Assert.Equal(ok, t.TryGetInt64(out long value));
        Assert.Equal(expected, value);
    }

    [Fact]
    public void Exposes_raw_value_and_escape_flag()
    {
        var t = new JsonTokenizer("[\"a\\nb\",\"plain\"]"u8);
        Assert.True(t.Read());
        Assert.True(t.Read());
        Assert.True(t.ValueHasEscapes);
        Assert.Equal("a\\nb", Encoding.UTF8.GetString(t.ValueSpan));
        Assert.True(t.Read());
        Assert.False(t.ValueHasEscapes);
        Assert.Equal(1, t.CurrentDepth);
    }

    [Fact]
    public void Tokenizing_allocates_nothing()
    {
        byte[] json = Encoding.UTF8.GetBytes("{\"a\":[1,2.5e3,\"x\\u00e9\\n\",true,false,null],\"b\":{\"c\":\"é😀\"}}");
        CountTokens(json);
        long before = GC.GetAllocatedBytesForCurrentThread();
        int count = CountTokens(json);
        long after = GC.GetAllocatedBytesForCurrentThread();
        Assert.Equal(16, count);
        Assert.Equal(0, after - before);
    }

    private static int CountTokens(byte[] json)
    {
        var t = new JsonTokenizer(json);
        int count = 0;
        while (t.Read())
        {
            count++;
        }

        return t.Error.IsError ? -1 : count;
    }

    internal static JsonParseError Tokenize(string json, out List<(JsonTokenKind Kind, string Value, int Offset)> tokens, int maxDepth = JsonTokenizer.MaxSupportedDepth)
        => Tokenize(Encoding.UTF8.GetBytes(json), out tokens, maxDepth);

    internal static JsonParseError Tokenize(byte[] json, out List<(JsonTokenKind Kind, string Value, int Offset)> tokens, int maxDepth = JsonTokenizer.MaxSupportedDepth)
    {
        tokens = [];
        var t = new JsonTokenizer(json, maxDepth);
        while (t.Read())
        {
            // Read returns false on the call that fails, so a true result always carries a real token.
            Assert.NotEqual(JsonTokenKind.None, t.Kind);
            Assert.Equal(t.Kind is JsonTokenKind.String or JsonTokenKind.PropertyName && t.ValueSpan.Contains((byte)'\\'), t.ValueHasEscapes);
            tokens.Add((t.Kind, Encoding.UTF8.GetString(t.ValueSpan), t.TokenOffset));
        }

        return t.Error;
    }
}
